<template>
  <div class="card">
    <!-- Шапка -->
    <div class="card-head">
      <div>
        <div class="card-tag">Пульс показателей</div>
        <h2 class="card-title">Сводка по компании</h2>
        <p class="card-sub">{{ period }}</p>
      </div>
      <div class="score-wrap">
        <div class="score" :style="{ color: scoreColor }">
          {{ score }}<span class="score-sign">%</span>
        </div>
        <div class="score-label">товарооборот</div>
      </div>
    </div>

    <!-- Метрики -->
    <div class="metrics">
      <div
          v-for="m in metrics"
          :key="m.key"
          class="metric-row"
      >
        <div class="metric-left">
          <span class="metric-icon">{{ m.icon }}</span>
          <span class="metric-name">{{ m.name }}</span>
        </div>
        <span class="badge" :class="m.planClass">
          {{ m.planPct >= 100 ? '▲' : '▼' }} {{ m.planPct }}% план
        </span>
        <span class="badge" :class="m.yoyClass">
          {{ m.yoy >= 0 ? '▲ +' : '▼ ' }}{{ m.yoy }}% год
        </span>
      </div>
    </div>

    <div class="divider"></div>

    <!-- Итоги -->
    <div class="summary-row">
      <span class="summary-label">✅ Выполняют план</span>
      <span class="summary-val green">{{ onPlan }} из {{ metrics.length }}</span>
    </div>
    <div class="summary-row">
      <span class="summary-label">📈 Растут к пр. году</span>
      <span class="summary-val green">{{ growing }} из {{ metrics.length }}</span>
    </div>
    <div class="summary-row">
      <span class="summary-label">📉 Падают к пр. году</span>
      <span class="summary-val red">{{ falling }} из {{ metrics.length }}</span>
    </div>
  </div>
</template>

<script>
import {dataStore} from '@/operations/requests'

function pctClass(p) {
  if (p >= 100) return 'green'
  if (p >= 85) return 'yellow'
  return 'red'
}

function yoyClass(p) {
  return p >= 0 ? 'green' : 'red'
}

export default {
  name: 'SummaryCardComponent',

  props: {
    selectedDate: {
      type: String,
      default: '',
    },
  },

  data() {
    return {
      metrics: [],
      period: '',
    }
  },

  mounted() {
    this.setData()
  },

  watch: {
    selectedDate(newVal, oldVal) {
      if (newVal !== oldVal) this.setData()
    },
  },

  computed: {
    score() {
      const products = this.metrics.find(m => m.key === 'products')
      return products ? products.planPct : 0
    },
    scoreColor() {
      if (this.score >= 100) return '#16a34a'
      if (this.score >= 85)  return '#d97706'
      return '#dc2626'
    },
    onPlan() {
      return this.metrics.filter(m => m.planPct >= 100).length
    },
    growing() {
      return this.metrics.filter(m => m.yoy >= 0).length
    },
    falling() {
      return this.metrics.filter(m => m.yoy < 0).length
    },
  },

  methods: {
    setData() {
      const payload = dataStore.getCompanyData()
      if (!payload) return

      const row = this.selectedDate
          ? payload.find(item => item.time === this.selectedDate)
          : payload[0]

      if (!row) return

      this.period = row.time

      const defs = [
        {
          key: 'products',
          name: 'Товарооборот',
          icon: '💰',
          f: row.products_f,
          p: row.products_p,
          past: row.products_past
        },
        {key: 'services', name: 'Услуги', icon: '🛡️', f: row.services_f, p: row.services_p, past: row.services_past},
        {key: 'trafic', name: 'Трафик', icon: '👥', f: row.trafic_f, p: row.trafic_p, past: row.trafic_past},
        {key: 'conver', name: 'Конверсия', icon: '🎯', f: row.conver_f, p: row.conver_p, past: row.conver_past},
        {key: 'check', name: 'Средний чек', icon: '🧾', f: row.check_f, p: row.check_p, past: row.check_past},
        {key: 'count', name: 'Позиций в чеке', icon: '📦', f: row.count_f, p: row.count_p, past: row.count_past},
        {key: 'credit', name: 'Кредит %', icon: '💳', f: row.credit_f, p: row.credit_p, past: row.credit_f},
      ]

      this.metrics = defs.map(m => {
        const planPct = m.p ? Math.round((m.f / m.p) * 100) : 0
        const yoy = m.past ? Math.round(((m.f - m.past) / m.past) * 100) : 0
        return {
          ...m,
          planPct,
          yoy,
          planClass: pctClass(planPct),
          yoyClass: yoyClass(yoy),
        }
      })
    },
  },
}
</script>

<style scoped>
.card {
  background: #ffffff;
  border-radius: 20px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.04), 0 12px 28px rgba(0, 0, 0, 0.07);
  padding: 22px 24px;
  font-family: 'Inter', system-ui, sans-serif;
  width: 100%;
  max-width: 480px;
}

/* ── Шапка ─────────────────────────────────────────── */
.card-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 18px;
}

.card-tag {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #6366f1;
  background: rgba(99, 102, 241, 0.08);
  border: 1px solid rgba(99, 102, 241, 0.2);
  padding: 3px 10px;
  border-radius: 20px;
  margin-bottom: 5px;
}

.card-title {
  font-size: 17px;
  font-weight: 700;
  color: #1e293b;
  letter-spacing: -0.3px;
  margin: 0 0 2px;
}

.card-sub {
  font-size: 11px;
  color: #94a3b8;
  font-weight: 500;
  margin: 0;
}

/* Скор */
.score-wrap {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  flex-shrink: 0;
}

.score {
  font-size: 30px;
  font-weight: 800;
  letter-spacing: -1.5px;
  line-height: 1;
  transition: color 0.3s;
}

.score-sign {
  font-size: 18px;
  font-weight: 700;
}

.score-label {
  font-size: 10px;
  color: #94a3b8;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

/* ── Метрики ───────────────────────────────────────── */
.metrics {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.metric-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-radius: 10px;
  background: #f8fafc;
  border: 1px solid #f1f5f9;
  transition: background 0.15s;

  &:hover {
    background: #f1f5f9;
  }
}

.metric-left {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.metric-icon {
  font-size: 15px;
  width: 22px;
  text-align: center;
  flex-shrink: 0;
}

.metric-name {
  font-size: 13px;
  font-weight: 600;
  color: #1e293b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Бейджи */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 20px;
  white-space: nowrap;
  flex-shrink: 0;
}

.badge.green {
  background: #dcfce7;
  color: #16a34a;
}

.badge.yellow {
  background: #fef3c7;
  color: #d97706;
}

.badge.red {
  background: #fee2e2;
  color: #dc2626;
}

/* ── Разделитель ───────────────────────────────────── */
.divider {
  height: 1px;
  background: #f1f5f9;
  margin: 14px 0 10px;
}

/* ── Итоги ─────────────────────────────────────────── */
.summary-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 5px 0;
}

.summary-label {
  font-size: 12px;
  color: #64748b;
  font-weight: 500;
}

.summary-val {
  font-size: 12px;
  font-weight: 700;

  &.green {
    color: #16a34a;
  }

  &.red {
    color: #dc2626;
  }
}
</style>
